import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    coupons = []
    for _ in range(m):
        q = int(next(iterator))
        w = int(next(iterator))
        coupons.append((w, q))

    coupons.sort(reverse=True)

    if n == 1:
        max_w = 0
        for w, q in coupons:
            if w > max_w:
                max_w = w
        print(max_w)
        return

    k = min(m, n)
    total_cost = 0
    used_count = 0

    for w, q in coupons:
        if used_count >= k:
            break
        total_cost += w
        used_count += 1

    if used_count == 1:
        print(total_cost)
    else:
        print(total_cost)

if __name__ == "__main__":
    solve()
